SELECT T0."Number" as "Agr No.", T1."DocNum" as "Rebate No.", T2."U_Alert" as "Alert Value",T2."U_POAF", T2."U_POAT", T2."U_RBTPRC", T2."U_RAmount", T0."StartDate", T0."EndDate", T0."BpCode", T0."BpName" , T3."U_BRANCHNM" as "Branch", (Select SUM("Purchase") from (Select SUM(IFNULL(A."Quantity",0)*IFNULL(A."INMPrice",0)) as "Purchase" from PCH1 A inner join OPCH B on A."DocEntry"=B."DocEntry" where B."CANCELED"='N' and B."CardCode" = T0."BpCode" and B."DocDate">=T0."StartDate" and B."DocDate"<=T0."EndDate" and B."BPLId"=T3."U_BRANCHID" UNION ALL Select -SUM(IFNULL(A."Quantity",0)*IFNULL(A."INMPrice",0)) as "Purchase" from RPC1 A inner join ORPC B on A."DocEntry"=B."DocEntry" where B."CANCELED"='N' and B."CardCode" = T0."BpCode" and B."DocDate">=T0."StartDate" and B."DocDate"<=T0."EndDate" and B."BPLId"=T3."U_BRANCHID")C ) as "Purchase Value"  FROM OOAT T0 inner join  "@SBO_SUPREBATE"  T1 ON T1."U_BASENT" = T0."AbsID" Left join "@SBO_SUPREBATE_C0"  T2 ON T1."DocEntry" = T2."DocEntry" Left join "@SBO_SUPREBATE_C1" T3 on T1."DocEntry"=T3."DocEntry"   where  T0."BpType" ='S' and T0."Status"='A' and IFNULL(T3."U_CHECKBOX",'N')='Y' and  (Select SUM("Purchase") from (Select SUM(IFNULL(A."Quantity",0)*IFNULL(A."INMPrice",0)) as "Purchase" from PCH1 A inner join OPCH B on A."DocEntry"=B."DocEntry" where B."CANCELED"='N' and B."CardCode" = T0."BpCode" and B."DocDate">=T0."StartDate" and B."DocDate"<=T0."EndDate" and B."BPLId"=T3."U_BRANCHID" UNION ALL Select -SUM(IFNULL(A."Quantity",0)*IFNULL(A."INMPrice",0)) as "Purchase" from RPC1 A inner join ORPC B on A."DocEntry"=B."DocEntry" where B."CANCELED"='N' and B."CardCode" = T0."BpCode" and B."DocDate">=T0."StartDate" and B."DocDate"<=T0."EndDate" and B."BPLId"=T3."U_BRANCHID")C ) >= T2."U_Alert"
